{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Dapagliflozin, which shares the identical ethoxyphenyl-chlorobenzyl aglycone with the query, has an absolute oral bioavailability of 78% (90% CI 73–83%) in healthy subjects measured by simultaneous IV 14C-microdose and therapeutic oral dosing, directly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tofogliflozin, a SGLT2 inhibitor with a spiro bicyclic sugar motif analogous to the query's modified sugar, has a mean absolute oral bioavailability of 97.5% in healthy volunteers, indicating that the spiro sugar modification does not impair absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Empagliflozin, a closely related SGLT2 inhibitor, has an absolute oral bioavailability of 90% in humans, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Bexagliflozin, another SGLT2 inhibitor with a similar glucoside core, has an absolute oral bioavailability of about 78% in humans, further supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a SGLT2 inhibitor analog with the same ethoxyphenyl-chlorobenzyl aglycone as dapagliflozin and a spiro bicyclic sugar similar to tofogliflozin. Direct human absolute bioavailability measurements for dapagliflozin (78%), tofogliflozin (97.5%), empagliflozin (90%), and bexagliflozin (78%) all exceed the 20% threshold, strongly supporting high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule; extrapolation relies on close SGLT2 analogs.",
    "Fasted-state-specific data are not explicitly reported in the cited records, though the high bioavailability of this class is not expected to be food-dependent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

